#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>

using namespace std;

/**
 * Problem: 10606 - How Big Is It?
 * 
 * 解題思路：
 * 1. 由於圓圈數量 m 很少 (m <= 8)，我們可以枚舉所有 m! 種排列。
 * 2. 對於每種排列，依序放置圓圈。每個圓圈必須放置在盡量靠左但又不與之前任何圓圈重疊的位置。
 * 3. 設第 i 個圓圈半徑為 r_i，中心座標為 (x_i, r_i)。
 * 4. x_i 必須滿足：對於所有 j < i, (x_i - x_j)^2 + (r_i - r_j)^2 >= (r_i + r_j)^2。
 *    推導得 x_i >= x_j + 2 * sqrt(r_i * r_j)。
 * 5. 初始 x_0 = r_0。最終寬度為 max(x_i + r_i) - min(x_i - r_i)。
 *    其實 min(x_i - r_i) 不一定是第一個圓，但所有圓都在 x=0 右側，所以寬度是各圓右邊緣的最大值。
 */

double solve() {
    int m;
    cin >> m;
    vector<double> r(m);
    for (int i = 0; i < m; ++i) cin >> r[i];
    sort(r.begin(), r.end());

    double min_width = 1e18;
    do {
        vector<double> x(m);
        double current_max = 0;
        for (int i = 0; i < m; ++i) {
            double x_i = r[i]; // 至少要離左牆 r[i]
            for (int j = 0; j < i; ++j) {
                x_i = max(x_i, x[j] + 2.0 * sqrt(r[i] * r[j]));
            }
            x[i] = x_i;
        }
        double width = 0;
        for (int i = 0; i < m; ++i) width = max(width, x[i] + r[i]);
        min_width = min(min_width, width);
    } while (next_permutation(r.begin(), r.end()));

    return min_width;
}

int main() {
    int n;
    cin >> n;
    while (n--) {
        cout << fixed << setprecision(3) << solve() << endl;
    }
    return 0;
}
